using System;using System.Globalization;using ForteMove.Web.Infrastructure;namespace ForteMove.Web.Driver{public partial class History:DriverPage{protected void Page_Load(object sender,EventArgs e){if(!IsPostBack){var items=ServiceFactory.CreateDriverOperationsService().GetHistory(CurrentPrincipalContext.UserAccountId);rptTrips.DataSource=items;rptTrips.DataBind();pnlEmpty.Visible=items.Count==0;}}protected string FormatDate(object value){return Convert.ToDateTime(value).ToString("dd MMM yyyy",CultureInfo.CurrentCulture);}}}
